CREATE TABLE societies(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,name text NOT NULL UNIQUE,kind text NOT NULL DEFAULT 'Sociedad',active boolean NOT NULL DEFAULT true);
INSERT INTO societies(name,kind) VALUES('General','General'),('Damas','Sociedad'),('Caballeros','Sociedad'),('Jóvenes','Sociedad'),('Niños','Sociedad'),('Pastorado','Ministerio') ON CONFLICT DO NOTHING;
CREATE TABLE weekly_programs(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,week_start date NOT NULL UNIQUE,created_by bigint REFERENCES users(id) ON DELETE SET NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE weekly_cults(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,program_id bigint NOT NULL REFERENCES weekly_programs(id) ON DELETE CASCADE,day_offset smallint NOT NULL CHECK(day_offset IN (1,2,3,6)),cult_name text NOT NULL CHECK(length(trim(cult_name)) BETWEEN 2 AND 120),starts_at time NOT NULL DEFAULT '19:00',topic_word text NOT NULL DEFAULT '',memory_instruction text NOT NULL DEFAULT '',manual_override boolean NOT NULL DEFAULT false,UNIQUE(program_id,day_offset));
CREATE TABLE weekly_items(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,cult_id bigint NOT NULL REFERENCES weekly_cults(id) ON DELETE CASCADE,position int NOT NULL CHECK(position>0),activity text NOT NULL CHECK(length(trim(activity)) BETWEEN 2 AND 120),member_id bigint REFERENCES members(id) ON DELETE SET NULL,responsible_name text NOT NULL DEFAULT '',starts_at time,minutes int CHECK(minutes BETWEEN 1 AND 240),topic text NOT NULL DEFAULT '',scripture text NOT NULL DEFAULT '',status text NOT NULL DEFAULT 'Pendiente' CHECK(status IN ('Pendiente','Notificado','Confirmado','Realizado','Cancelado')),notes text NOT NULL DEFAULT '',UNIQUE(cult_id,position));
CREATE TABLE weekly_invitations(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,program_id bigint NOT NULL REFERENCES weekly_programs(id) ON DELETE CASCADE,event_date date NOT NULL,event_time time,entity text NOT NULL,activity text NOT NULL,place text NOT NULL DEFAULT '',contact text NOT NULL DEFAULT '',phone text NOT NULL DEFAULT '',modality text NOT NULL DEFAULT 'Presencial',responsible text NOT NULL DEFAULT '',status text NOT NULL DEFAULT 'Pendiente',notes text NOT NULL DEFAULT '');
CREATE TABLE weekly_publications(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,program_id bigint NOT NULL REFERENCES weekly_programs(id) ON DELETE RESTRICT,revision int NOT NULL CHECK(revision>0),snapshot jsonb NOT NULL,created_by bigint REFERENCES users(id) ON DELETE SET NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(program_id,revision));
INSERT INTO permissions(code) VALUES('program.read'),('program.write'),('program.publish') ON CONFLICT DO NOTHING;
INSERT INTO role_permissions(role_id,permission_code) SELECT r.id,p.code FROM roles r JOIN permissions p ON p.code IN ('program.read','program.write','program.publish') WHERE r.name='Administrador' ON CONFLICT DO NOTHING;
INSERT INTO role_permissions(role_id,permission_code) SELECT r.id,p.code FROM roles r JOIN permissions p ON p.code IN ('program.read','program.write') WHERE r.name='Secretaría' ON CONFLICT DO NOTHING;
INSERT INTO role_permissions(role_id,permission_code) SELECT r.id,p.code FROM roles r JOIN permissions p ON p.code='program.read' WHERE r.name='Consulta' ON CONFLICT DO NOTHING;
